cards.py:
"""Cards are ints 0..51: rank = c >> 2 (0='2' .. 12='A'), suit = c & 3."""

RANKS = "23456789TJQKA"
SUITS = "cdhs"

HIGH, PAIR, TWO_PAIR, TRIPS, STRAIGHT, FLUSH, FULL_HOUSE, QUADS, STRAIGHT_FLUSH = range(9)
CATEGORY_NAMES = ["high card", "pair", "two pair", "trips", "straight", "flush",
                  "full house", "quads", "straight flush"]


def card_str(c):
    return RANKS[c >> 2] + SUITS[c & 3]


def cards_str(cs):
    return " ".join(card_str(c) for c in cs)


def parse(s):
    return RANKS.index(s[0].upper()) * 4 + SUITS.index(s[1].lower())


def straight_high(mask):
    """Highest rank of a straight in a 13-bit rank mask, or -1. Handles the A-5 wheel."""
    m = (mask << 1) | ((mask >> 12) & 1)  # bit 0 = ace-low
    for high in range(13, 3, -1):
        if (m >> (high - 4)) & 0x1F == 0x1F:
            return high - 1
    return -1


def _val(cat, ranks):
    v = cat
    for i in range(5):
        v = v * 16 + (ranks[i] + 1 if i < len(ranks) else 0)
    return v


def category(value):
    return value >> 20


def evaluate(cards):
    """Score the best 5-card hand from 1..7 cards. Higher is better."""
    counts = [0] * 13
    suit_cnt = [0] * 4
    suit_mask = [0] * 4
    mask = 0
    for c in cards:
        r = c >> 2
        s = c & 3
        counts[r] += 1
        mask |= 1 << r
        suit_cnt[s] += 1
        suit_mask[s] |= 1 << r

    # With at most 7 cards a flush can't coexist with quads or a full house.
    for s in range(4):
        if suit_cnt[s] >= 5:
            sm = suit_mask[s]
            sh = straight_high(sm)
            if sh >= 0:
                return _val(STRAIGHT_FLUSH, [sh])
            return _val(FLUSH, [r for r in range(12, -1, -1) if sm >> r & 1][:5])

    quads, trips, pairs, singles = [], [], [], []
    for r in range(12, -1, -1):
        n = counts[r]
        if n == 4:
            quads.append(r)
        elif n == 3:
            trips.append(r)
        elif n == 2:
            pairs.append(r)
        elif n == 1:
            singles.append(r)

    if quads:
        q = quads[0]
        rest = [r for r in range(12, -1, -1) if counts[r] and r != q]
        return _val(QUADS, [q] + rest[:1])
    if trips and (len(trips) > 1 or pairs):
        return _val(FULL_HOUSE, [trips[0], max(trips[1:] + pairs)])
    sh = straight_high(mask)
    if sh >= 0:
        return _val(STRAIGHT, [sh])
    if trips:
        return _val(TRIPS, [trips[0]] + singles[:2])
    if len(pairs) >= 2:
        kick = sorted(pairs[2:] + singles, reverse=True)[:1]
        return _val(TWO_PAIR, pairs[:2] + kick)
    if pairs:
        return _val(PAIR, [pairs[0]] + singles[:3])
    return _val(HIGH, singles[:5])

preflop.py:
"""Preflop table for the 169 starting hands: equity vs one random hand and a percentile rank.

Run `python3 preflop.py` once to build preflop_table.json (~15s). The bot only looks it up.
"""
import json
import os
import random

from cards import RANKS, evaluate

PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "preflop_table.json")


def hand_key(c1, c2):
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2:
        r1, r2 = r2, r1
    if r1 == r2:
        return RANKS[r1] * 2
    return RANKS[r1] + RANKS[r2] + ("s" if (c1 & 3) == (c2 & 3) else "o")


def _representatives():
    reps = {}
    for a in range(13):
        for b in range(a + 1):
            if a == b:
                reps[RANKS[a] * 2] = (a * 4, a * 4 + 1, 6)
            else:
                reps[RANKS[a] + RANKS[b] + "s"] = (a * 4, b * 4, 4)
                reps[RANKS[a] + RANKS[b] + "o"] = (a * 4, b * 4 + 1, 12)
    return reps


def compute(sims=20000, seed=0):
    rng = random.Random(seed)
    table = {}
    reps = _representatives()
    for key, (c1, c2, combos) in reps.items():
        rest = [c for c in range(52) if c not in (c1, c2)]
        score = 0.0
        for _ in range(sims):
            draw = rng.sample(rest, 7)
            board = draw[2:]
            me = evaluate([c1, c2] + board)
            opp = evaluate(draw[:2] + board)
            score += 1.0 if me > opp else 0.5 if me == opp else 0.0
        table[key] = {"eq": score / sims, "combos": combos}

    cum = 0
    for key in sorted(table, key=lambda k: -table[k]["eq"]):
        cum += table[key]["combos"]
        table[key]["pct"] = cum / 1326.0  # fraction of all hands at least this strong
    return table


def load():
    if not os.path.exists(PATH):
        table = compute()
        with open(PATH, "w") as f:
            json.dump(table, f, indent=1)
        return table
    with open(PATH) as f:
        return json.load(f)


TABLE = load()

if __name__ == "__main__":
    top = sorted(TABLE, key=lambda k: TABLE[k]["pct"])
    for k in top[:15] + ["..."] + top[-5:]:
        if k == "...":
            print("...")
            continue
        print(f"{k:4s} eq={TABLE[k]['eq']:.3f} top {TABLE[k]['pct'] * 100:5.1f}%")


# ---------- equity vs a top-X% range (used for ICM all-in decisions) ----------
RANGE_GRID = [0.03, 0.06, 0.1, 0.15, 0.2, 0.3, 0.45, 0.65, 1.0]
RANGE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "range_equity.json")


def _combos_by_strength():
    combos = [(a, b) for a in range(52) for b in range(a)]
    return sorted(combos, key=lambda c: TABLE[hand_key(*c)]["pct"])


def _range_row(args):
    key, sims = args
    c1, c2, _ = _representatives()[key]
    rng = random.Random(hash(key) & 0xFFFF)
    combos = _combos_by_strength()
    row = []
    for w in RANGE_GRID:
        rngcombos = [c for c in combos if TABLE[hand_key(*c)]["pct"] <= max(w, 0.005)
                     and c1 not in c and c2 not in c]
        score = 0.0
        for _ in range(sims):
            o = rngcombos[rng.randrange(len(rngcombos))]
            rest = [c for c in range(52) if c not in (c1, c2, o[0], o[1])]
            board = rng.sample(rest, 5)
            me = evaluate([c1, c2] + board)
            op = evaluate(list(o) + board)
            score += 1.0 if me > op else 0.5 if me == op else 0.0
        row.append(score / sims)
    return key, row


def compute_range_equity(sims=3000):
    from multiprocessing import Pool
    with Pool(max(1, os.cpu_count() - 2)) as pool:
        rows = pool.map(_range_row, [(k, sims) for k in _representatives()])
    return dict(rows)


def load_range_equity():
    if not os.path.exists(RANGE_PATH):
        data = compute_range_equity()
        with open(RANGE_PATH, "w") as f:
            json.dump(data, f)
        return data
    with open(RANGE_PATH) as f:
        return json.load(f)


def equity_vs_range(key, width, table):
    """Linear interpolation of my hand's equity vs the opponent's top-`width` range."""
    row = table[key]
    if width <= RANGE_GRID[0]:
        return row[0]
    for i in range(1, len(RANGE_GRID)):
        if width <= RANGE_GRID[i]:
            lo, hi = RANGE_GRID[i - 1], RANGE_GRID[i]
            t = (width - lo) / (hi - lo)
            return row[i - 1] * (1 - t) + row[i] * t
    return row[-1]

mybot.py:
"""Parameterized sit-and-go bot (v2).

v1 + two upgrades:
  1. Opponent profiles per seat (VPIP, PFR, shove rate, fold-to-raise, postflop fold rate).
     Used to read a raiser's range, steal from players who fold too much, and stop bluffing
     calling stations.
  2. Real ICM. All-in calls compare expected *points* of calling vs folding, using the
     shover's estimated range. Everything else scales by an "ICM risk premium": how much
     more than 50% equity a stack-for-stack flip needs right now.
Every decision is lookups plus a few O(n^2) loops, so it stays far below the 1 ms limit.
"""
import gc
import json
import os
import random

from cards import evaluate, straight_high, PAIR, TWO_PAIR, TRIPS, STRAIGHT, FLUSH, FULL_HOUSE
from preflop import TABLE, hand_key, load_range_equity, equity_vs_range

RANGE_EQ = load_range_equity()
PRIZES = [10, 5, 2]
# Card pair -> hand key / strength percentile, so a decision never builds strings.
KEY = [[hand_key(a, b) if a != b else None for b in range(52)] for a in range(52)]
PCT = [[TABLE[KEY[a][b]]["pct"] if a != b else 1.0 for b in range(52)] for a in range(52)]

DEFAULT_PARAMS = {
    "open_pct": 0.12,         # unopened raise range, earliest position (fraction of hands)
    "open_late_bonus": 0.18,  # extra range when last to act
    "open_size": 2.5,         # open raise in big blinds (+1 per limper)
    "threebet_pct": 0.025,    # re-raise range vs a typical raiser
    "call_raise_pct": 0.06,   # flat-call range vs a typical raiser
    "push_bb": 12.0,          # at or below this many big blinds: push/fold only
    "push_base": 0.10,        # push range at push_bb from early position
    "push_exp": 1.0,          # how fast the push range widens as the stack shrinks
    "push_late_mult": 2.5,    # push range multiplier when last to act
    "bet_eq": 0.55,           # postflop: bet for value above this strength
    "raise_eq": 0.82,         # postflop: raise above this strength
    "call_margin": 0.03,      # postflop: need this much over pot odds to call
    "value_frac": 0.66,       # value bet size as a fraction of the pot
    "cbet": 0.55,             # heads-up flop continuation-bet frequency
    # opponent modeling
    "min_samples": 15,        # hands observed before trusting a seat's stats
    "default_range": 0.15,    # assumed shove/raise range for unknown players
    "range_mult": 1.3,        # observed raise frequency -> range width
    "ref_pfr": 0.12,          # raise frequency treated as "normal"
    "steal_widen": 1.0,       # widen opens/pushes when players behind fold too much
    "station_value": 0.08,    # bet thinner for value vs players who rarely fold
    # ICM
    "icm_k": 1.5,             # shrink ranges by (1 - icm_k * premium)
    "icm_post_k": 1.0,        # postflop: add premium * commitment to the required equity
    "icm_call_margin": 0.0,   # all-in call needs this many expected points over folding
    # v3 postflop aggression (defaults switch each one off, so v3 at defaults plays exactly like v2)
    "stab_fold": 1.01,        # heads-up, checked to: bet any hand if the opponent folds to bets this often
    "semibluff": 0.0,         # chance to bet (or raise) a drawing hand instead of checking (or calling)
    "barrel": 0.0,            # chance to bet the turn again after betting the flop
    "bluff_frac": 0.5,        # size of stabs, semi-bluffs and barrels as a fraction of the pot
    "pileup_range": 0.0,      # when 2+ opponents are already all-in, assume they shove this wide (0 = off)
    "late_from": 10 ** 9,     # from this hand number on, play with `late_params` instead (off by default)
    "late_params": None,      # a second settings dict for the late game
}

BOUNDS = {
    "open_pct": (0.04, 0.35), "open_late_bonus": (0.0, 0.5), "open_size": (2.0, 4.0),
    "threebet_pct": (0.005, 0.1), "call_raise_pct": (0.01, 0.2), "push_bb": (6.0, 45.0),
    "push_base": (0.03, 0.4), "push_exp": (0.3, 2.0), "push_late_mult": (1.0, 5.0),
    "bet_eq": (0.3, 0.85), "raise_eq": (0.6, 0.98), "call_margin": (-0.1, 0.2),
    "value_frac": (0.3, 1.2), "cbet": (0.0, 1.0),
    "min_samples": (8, 40), "default_range": (0.05, 0.4), "range_mult": (0.8, 2.5),
    "ref_pfr": (0.05, 0.3), "steal_widen": (0.0, 4.0), "station_value": (0.0, 0.2),
    "icm_k": (0.0, 5.0), "icm_post_k": (0.0, 3.0), "icm_call_margin": (-0.3, 0.3),
    "stab_fold": (0.3, 1.01), "semibluff": (0.0, 1.0), "barrel": (0.0, 1.0), "bluff_frac": (0.25, 1.2), "pileup_range": (0.0, 1.0),
}

TUNED_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "best_params.json")


def load_tuned():
    path = os.environ.get("BOT_PARAMS", TUNED_PATH)  # e.g. BOT_PARAMS=best_params_minimal.json
    if os.path.exists(path):
        with open(path) as f:
            saved = json.load(f)
        return {k: v for k, v in saved.items() if k in DEFAULT_PARAMS}
    return None


def icm_me(stacks, i):
    """Expected points for stacks[i] (Malmuth-Harville). O(n^2): cheap enough per decision."""
    s = stacks[i]
    if s <= 0:
        return 0.0
    others = [x for j, x in enumerate(stacks) if j != i and x > 0]
    S = float(s + sum(others))
    ev = PRIZES[0] * s / S
    if not others:
        return ev
    p2 = p3 = 0.0
    third = len(others) > 1
    for a, sa in enumerate(others):
        pa = sa / S
        rest = S - sa
        p2 += pa * s / rest
        if third:
            inner = 0.0
            for b, sb in enumerate(others):
                if b != a:
                    inner += sb / (rest - sb)
            p3 += pa / rest * inner
    ev += PRIZES[1] * p2
    if third:
        ev += PRIZES[2] * p3 * s
    return ev


# The tables above live for the whole game: move them out of the garbage collector's view so its
# pauses (which can land inside a timed decision) have less to scan.
gc.collect()
gc.freeze()


class Profile:
    __slots__ = ("hands", "vpip", "pfr", "shoves", "faced_raise", "fold_raise", "faced_bet", "fold_bet")

    def __init__(self):
        for k in self.__slots__:
            setattr(self, k, 0)


class MyBot:
    def __init__(self, params=None, seed=None):
        self.p = dict(DEFAULT_PARAMS)
        if params:
            self.p.update(params)
        self.rng = random.Random(seed)
        self.prof = {}
        self.errors = 0      # exceptions caught in get_action (each one became a check/fold)
        self._hand = -1      # hand number the caches below belong to
        self._icm = {}       # (stack totals, opponent) -> ICM premium
        self._board = {}     # board tuple -> evaluate(board)
        p = self.p
        # Widest range any unopened decision can use; anything weaker folds immediately.
        self._max_open = min(1.0, (p["open_pct"] + p["open_late_bonus"]) * (1 + max(0.0, p["steal_widen"]) * 0.45))

    # ---------- engine hooks ----------
    def get_action(self, s):
        try:
            if s["hand_number"] != self._hand:
                if s["hand_number"] >= self.p["late_from"] and self.p.get("late_params"):
                    late = dict(self.p["late_params"])
                    late["late_from"], late["late_params"] = 10 ** 9, None
                    self.p = dict(DEFAULT_PARAMS, **late)
                    p = self.p
                    self._max_open = min(1.0, (p["open_pct"] + p["open_late_bonus"]) * (1 + max(0.0, p["steal_widen"]) * 0.45))
                self._hand = s["hand_number"]
                self._icm.clear()
                self._board.clear()
            return self.preflop(s) if s["street"] == 0 else self.postflop(s)
        except Exception:
            self.errors += 1
            try:
                return self.passive(s)
            except Exception:
                return ("fold",)

    def on_hand_end(self, info):
        gc.collect(0)  # untimed: clear young garbage now rather than mid-decision
        seen, vpip, pfr, shoves = set(), set(), set(), set()
        faced, folded = set(), set()
        raised = False
        post_faced, post_folded = {}, {}
        street_bet = {}
        for street, seat, kind, _amt, allin in info["history"]:
            seen.add(seat)
            if kind in ("sb", "bb"):
                continue
            if street == 0:
                if kind in ("call", "raise"):
                    vpip.add(seat)
                if kind == "raise":
                    pfr.add(seat)
                    if allin:
                        shoves.add(seat)
                if raised and seat not in faced:
                    faced.add(seat)
                    if kind == "fold":
                        folded.add(seat)
                if kind == "raise":
                    raised = True
            else:
                if street_bet.get(street):
                    post_faced[seat] = post_faced.get(seat, 0) + 1
                    post_folded[seat] = post_folded.get(seat, 0) + (kind == "fold")
                if kind == "raise":
                    street_bet[street] = True
        for seat in seen:
            pr = self.prof.get(seat)
            if pr is None:
                pr = self.prof[seat] = Profile()
            pr.hands += 1
            pr.vpip += seat in vpip
            pr.pfr += seat in pfr
            pr.shoves += seat in shoves
            pr.faced_raise += seat in faced
            pr.fold_raise += seat in folded
            pr.faced_bet += post_faced.get(seat, 0)
            pr.fold_bet += post_folded.get(seat, 0)

    # ---------- opponent reads ----------
    def known(self, seat):
        pr = self.prof.get(seat)
        return pr if pr and pr.hands >= self.p["min_samples"] else None

    def raise_range(self, seat, shove):
        """Estimated width (fraction of hands) of this seat's raising / shoving range."""
        pr = self.known(seat)
        if not pr:
            return self.p["default_range"]
        freq = (pr.shoves if shove and pr.shoves else pr.pfr) / pr.hands
        return min(1.0, max(0.02, freq * self.p["range_mult"]))

    def fold_to_raise(self, seat):
        pr = self.prof.get(seat)
        if not pr or pr.faced_raise < 6:
            return 0.5
        return pr.fold_raise / pr.faced_raise

    def fold_to_bet(self, seat):
        pr = self.prof.get(seat)
        return (pr.fold_bet + 1) / (pr.faced_bet + 2) if pr else 0.5

    def is_station(self, seat):
        pr = self.prof.get(seat)
        return bool(pr) and pr.faced_bet >= 8 and pr.fold_bet / pr.faced_bet < 0.2

    # ---------- helpers ----------
    @staticmethod
    def passive(s):
        return ("check",) if s["to_call"] == 0 else ("fold",)

    @staticmethod
    def raise_to(s, target):
        if not s["can_raise"]:
            return ("call",)
        target = int(max(s["min_raise_to"], min(target, s["max_raise_to"])))
        if target >= 0.7 * s["max_raise_to"]:  # don't leave a sliver behind
            target = s["max_raise_to"]
        return ("raise", target)

    @staticmethod
    def last_raiser(s):
        for street, seat, kind, _a, _ai in reversed(s["history"]):
            if street == s["street"] and kind == "raise":
                return seat
        return None

    def aggressor(self, s):
        """Who made the bet I'm facing: from the history if there is one, otherwise the seat with the
        biggest bet in front of it, otherwise the biggest stack (APIs without history still work)."""
        seat = self.last_raiser(s)
        if seat is not None:
            return seat
        me = s["seat"]
        others = [t for t in s["stacks"] if t != me and t not in s["folded"]] or [t for t in s["stacks"] if t != me]
        if not others:
            return None
        return max(others, key=lambda t: (s["bets"].get(t, 0), s["stacks"][t]))

    @staticmethod
    def seats_behind(s):
        acted = {seat for st, seat, k, _a, _ai in s["history"] if st == s["street"] and k not in ("sb", "bb")}
        out = set(s["folded"]) | set(s["allin"])
        return [t for t in s["stacks"] if t != s["seat"] and t not in acted and t not in out]

    def icm_premium(self, s, opp=None):
        """Extra equity (above 0.5) a stack-for-stack flip needs in ICM terms right now."""
        key = (tuple(s["stacks"].values()), opp)
        hit = self._icm.get(key)
        if hit is None:
            hit = self._icm[key] = self._icm_premium(s, opp)
        return hit

    def _icm_premium(self, s, opp):
        seats = list(s["stacks"])
        me = s["seat"]
        if opp is None:
            others = [t for t in seats if t != me]
            if not others:
                return 0.0
            opp = max(others, key=lambda t: s["stacks"][t])
        st = [s["stacks"][t] for t in seats]
        i, j = seats.index(me), seats.index(opp)
        eff = min(st[i], st[j])
        now = icm_me(st, i)
        win, lose = st[:], st[:]
        win[i] += eff
        win[j] -= eff
        lose[i] -= eff
        lose[j] += eff
        ev_win, ev_lose = icm_me(win, i), self.bust_points(s) if lose[i] == 0 else icm_me(lose, i)
        if ev_win <= ev_lose:
            return 0.0
        return max(0.0, (now - ev_lose) / (ev_win - ev_lose) - 0.5)

    @staticmethod
    def bust_points(s):
        place = s["players_left"]
        return PRIZES[place - 1] if place <= len(PRIZES) else 0.0

    def allin_call_ev(self, s, opp, eq):
        """Expected points of calling an all-in-sized bet minus expected points of folding."""
        seats = list(s["stacks"])
        me = s["seat"]
        i, j = seats.index(me), seats.index(opp)
        my_bet, opp_bet = s["bets"][me], s["bets"][opp]
        dead = s["pot"] - my_bet - opp_bet
        base = [s["stacks"][t] - s["bets"][t] for t in seats]  # everyone's chips minus this street's bets
        me_tot, opp_tot = s["stacks"][me], s["stacks"][opp]
        eff = min(me_tot, opp_tot)

        win, lose, fold = base[:], base[:], base[:]
        win[i] = me_tot + eff + dead
        win[j] = opp_tot - eff
        lose[i] = me_tot - eff
        lose[j] = opp_tot + eff + dead
        fold[i] = me_tot - my_bet
        fold[j] = opp_tot + my_bet + dead
        ev_lose = self.bust_points(s) if lose[i] == 0 else icm_me(lose, i)
        ev_call = eq * icm_me(win, i) + (1 - eq) * ev_lose
        ev_fold = self.bust_points(s) if fold[i] == 0 else icm_me(fold, i)
        return ev_call - ev_fold

    def _max_push(self, s):
        p = self.p
        mine = s["stacks"][s["seat"]]
        biggest_other = max((v for t, v in s["stacks"].items() if t != s["seat"]), default=mine)
        eff_bb = min(mine, biggest_other) / s["big_blind"]
        return (p["push_base"] * (p["push_bb"] / max(eff_bb, 1.0)) ** p["push_exp"]
                * p["push_late_mult"] * (1 + max(0.0, p["steal_widen"]) * 0.45))

    # ---------- preflop ----------
    def preflop(self, s):
        p = self.p
        bb = s["big_blind"]
        c1, c2 = s["hole"]
        pct = PCT[c1][c2]
        if s["current_bet"] <= bb and pct > self._max_open and pct > self._max_push(s):
            # Unopened and weaker than the widest open or push range we could use: fold before any other work.
            return self.passive(s)
        key = KEY[c1][c2]
        me = s["seat"]
        mine = s["stacks"][me]
        biggest_other = max((v for t, v in s["stacks"].items() if t != me), default=mine)
        eff_bb = min(mine, biggest_other) / bb
        late = 1.0 - s["players_behind"] / max(1, s["players_left"] - 1)
        to_call = s["to_call"]

        if s["current_bet"] <= bb:  # unopened (maybe limped)
            push = eff_bb <= p["push_bb"]
            if push:
                base = p["push_base"] * (p["push_bb"] / max(eff_bb, 1.0)) ** p["push_exp"]
                pos = 1 + (p["push_late_mult"] - 1) * late
            else:
                base, pos = p["open_pct"] + p["open_late_bonus"] * late, 1.0
            # Steal widening multiplies the range by 1..steal_max and ICM by 0.25..1, so most
            # hands are decided by these bounds without computing either (same decisions, less work).
            lo = base * pos * 0.25 * (1 - 1e-9)
            steal_max = 1 + max(0.0, p["steal_widen"]) * 0.45 * late
            if pct > base * pos * steal_max * (1 + 1e-9):
                return self.passive(s)
            if pct > lo:
                behind = self.seats_behind(s)
                ftr = sum(self.fold_to_raise(t) for t in behind) / len(behind) if behind else 1.0
                steal = 1 + p["steal_widen"] * max(0.0, ftr - 0.55) * late
                rng = base * (pos * steal) if push else base * steal
                if pct > rng:
                    return self.passive(s)
                if pct > rng * 0.25 and pct > rng * max(0.25, 1 - p["icm_k"] * self.icm_premium(s)):
                    return self.passive(s)
            if push:
                return self.raise_to(s, s["max_raise_to"])
            limpers = sum(1 for st, _, k, _a, _ai in s["history"] if st == 0 and k == "call")
            return self.raise_to(s, bb * (p["open_size"] + limpers))

        raiser = self.aggressor(s)
        if raiser is None:
            return self.passive(s)
        if to_call >= 0.4 * s["stack"] or eff_bb <= p["push_bb"]:
            # Committing decision: compare expected points of going all-in vs folding.
            shove = raiser is not None and raiser in s["allin"]
            width = self.raise_range(raiser, shove) if raiser is not None else p["default_range"]
            if p["pileup_range"] > width and sum(1 for t in s["allin"] if t != me) >= 2:
                width = p["pileup_range"]  # several players already all-in: likely loose bots piling in
            eq = equity_vs_range(key, width, RANGE_EQ)
            others_in = sum(1 for t in s["stacks"] if t not in (me, raiser) and s["bets"][t] > bb)
            eq = eq ** (1 + 0.8 * others_in)  # crude multiway discount
            if self.allin_call_ev(s, raiser, eq) > p["icm_call_margin"]:
                return self.raise_to(s, s["max_raise_to"])
            return self.passive(s)

        # Normal raise: scale ranges by how wide this raiser opens and by ICM pressure.
        width = self.raise_range(raiser, False) if raiser is not None else p["ref_pfr"]
        looseness = min(2.5, max(0.4, width / (p["ref_pfr"] * p["range_mult"])))
        if pct <= p["threebet_pct"] * looseness:
            return self.raise_to(s, s["current_bet"] * 3)
        call_rng = p["call_raise_pct"] * looseness
        if pct > call_rng:
            return self.passive(s)
        if pct <= call_rng * 0.25 or pct <= call_rng * max(0.25, 1 - p["icm_k"] * self.icm_premium(s, raiser)):
            return ("call",)
        return self.passive(s)

    # ---------- postflop ----------
    def made_strength(self, hole, board):
        v = evaluate(hole + board)
        cat = v >> 20
        bkey = tuple(board)
        bv = self._board.get(bkey)
        if bv is None:
            bv = self._board[bkey] = evaluate(board)
        bcat = bv >> 20
        if cat <= bcat:
            return 0.12  # playing the board
        branks = sorted((c >> 2 for c in board), reverse=True)
        hranks = [c >> 2 for c in hole]
        if cat == PAIR:
            pr = ((v >> 16) & 15) - 1
            if hranks[0] == hranks[1] and pr > branks[0]:
                return 0.72  # overpair
            if pr == branks[0]:
                kicker = max((r for r in hranks if r != pr), default=12)
                return 0.6 if kicker >= 9 else 0.52  # top pair
            return 0.42 if pr >= branks[1] else 0.3
        if cat == TWO_PAIR:
            return 0.5 if bcat == PAIR else 0.78
        if cat == TRIPS:
            return 0.75 if bcat == PAIR else 0.86
        return {STRAIGHT: 0.87, FLUSH: 0.91, FULL_HOUSE: 0.96}.get(cat, 0.99)

    @staticmethod
    def draw_equity(hole, board, street):
        if street == 3:
            return 0.0
        cards = hole + board
        outs = 0.0
        for su in range(4):
            if sum(1 for c in cards if c & 3 == su) == 4 and any(c & 3 == su for c in hole):
                outs += 9
        mask = 0
        for c in cards:
            mask |= 1 << (c >> 2)
        if straight_high(mask) < 0:
            ranks = sum(1 for r in range(13) if not mask >> r & 1 and straight_high(mask | 1 << r) >= 0)
            outs += min(8, 4 * ranks) * (0.7 if outs else 1.0)
        return min(0.6, outs * (0.04 if street == 1 else 0.02))

    def postflop(self, s):
        p = self.p
        hole, board = list(s["hole"]), s["board"]
        me = s["seat"]
        n_opp = max(1, s["active_in_hand"] - 1)
        made = self.made_strength(hole, board) ** (1 + 0.6 * (n_opp - 1))
        draw = self.draw_equity(hole, board, s["street"])
        e = max(made, draw)
        pot, to_call = s["pot"], s["to_call"]
        opps = [t for t in s["stacks"] if t != me and t not in s["folded"]]
        vs_station = n_opp == 1 and self.is_station(opps[0])

        if to_call == 0:
            if e >= p["bet_eq"] - (p["station_value"] if vs_station else 0.0):
                return self.raise_to(s, s["bet"] + p["value_frac"] * pot)
            raised_pre = any(st == 0 and seat == me and k == "raise"
                             for st, seat, k, _a, _ai in s["history"])
            if (raised_pre and n_opp == 1 and not vs_station and s["street"] == 1
                    and self.rng.random() < p["cbet"]):
                return self.raise_to(s, s["bet"] + 0.5 * pot)
            if n_opp == 1 and not vs_station:
                bluff = self.raise_to(s, s["bet"] + p["bluff_frac"] * pot)
                if p["semibluff"] > 0 and draw >= 0.15 and self.rng.random() < p["semibluff"]:
                    return bluff
                if (p["barrel"] > 0 and s["street"] == 2
                        and any(st == 1 and seat == me and k == "raise" for st, seat, k, _a, _ai in s["history"])
                        and self.rng.random() < p["barrel"]):
                    return bluff
                if p["stab_fold"] <= 1.0 and self.fold_to_bet(opps[0]) >= p["stab_fold"]:
                    return bluff
            return ("check",)

        odds = to_call / (pot + to_call)
        if e >= p["raise_eq"]:
            return self.raise_to(s, s["current_bet"] + max(s["big_blind"], p["value_frac"] * (pot + to_call)))
        if (p["semibluff"] > 0 and n_opp == 1 and not vs_station and draw >= 0.15 and s["can_raise"]
                and to_call <= 0.25 * s["stack"] and self.rng.random() < p["semibluff"] * 0.5):
            return self.raise_to(s, s["current_bet"] + max(s["big_blind"], p["bluff_frac"] * (pot + to_call)))
        commit = min(1.0, to_call / max(1, s["stack"]))
        base = odds + p["call_margin"]
        # The ICM premium is between 0 and 0.5, so skip computing it when it can't change the answer.
        if e < base - 1e-12:
            return ("fold",)
        if p["icm_post_k"] >= 0 and e >= base + p["icm_post_k"] * 0.5 * commit + 1e-12:
            return ("call",)
        need = base + p["icm_post_k"] * self.icm_premium(s, self.last_raiser(s)) * commit
        return ("call",) if e >= need else ("fold",)

mybot_v1.py:
"""Parameterized sit-and-go bot: preflop ranges, push/fold when short, pot-odds postflop,
ICM tightening near the bubble, and a simple maniac detector. Every decision is a few
lookups and arithmetic, so it stays far below the 1 ms limit."""
import json
import os
import random

from cards import (evaluate, straight_high, HIGH, PAIR, TWO_PAIR, TRIPS, STRAIGHT, FLUSH, FULL_HOUSE)
from preflop import TABLE, hand_key

DEFAULT_PARAMS = {
    "open_pct": 0.12,         # unopened raise range, earliest position (fraction of hands)
    "open_late_bonus": 0.18,  # extra range when last to act
    "open_size": 2.5,         # open raise in big blinds (+1 per limper)
    "threebet_pct": 0.025,    # re-raise range vs a normal raise
    "call_raise_pct": 0.06,   # flat-call range vs a normal raise
    "push_bb": 12.0,          # at or below this many big blinds: push/fold only
    "push_base": 0.10,        # push range at push_bb from early position
    "push_exp": 1.0,          # how fast the push range widens as the stack shrinks
    "push_late_mult": 2.5,    # push range multiplier when last to act
    "call_allin_pct": 0.07,   # call range vs a shove at even pot odds
    "bubble_tighten": 0.65,   # multiply calling ranges by this near the money / cap
    "maniac_widen": 2.2,      # multiply calling ranges vs detected maniacs
    "maniac_rate": 0.15,      # preflop-shove frequency that marks a maniac
    "bet_eq": 0.55,           # postflop: bet for value above this strength
    "raise_eq": 0.82,         # postflop: raise above this strength
    "call_margin": 0.03,      # postflop: need this much over pot odds to call
    "icm_margin": 0.06,       # extra margin when ICM pressure applies
    "value_frac": 0.66,       # value bet size as a fraction of the pot
    "cbet": 0.55,             # heads-up flop continuation-bet frequency
}

BOUNDS = {
    "open_pct": (0.04, 0.35), "open_late_bonus": (0.0, 0.5), "open_size": (2.0, 4.0),
    "threebet_pct": (0.005, 0.1), "call_raise_pct": (0.01, 0.2), "push_bb": (6.0, 20.0),
    "push_base": (0.03, 0.4), "push_exp": (0.3, 2.0), "push_late_mult": (1.0, 5.0),
    "call_allin_pct": (0.02, 0.3), "bubble_tighten": (0.3, 1.0), "maniac_widen": (1.0, 5.0),
    "maniac_rate": (0.05, 0.4), "bet_eq": (0.3, 0.85), "raise_eq": (0.6, 0.98),
    "call_margin": (-0.1, 0.2), "icm_margin": (0.0, 0.2), "value_frac": (0.3, 1.2), "cbet": (0.0, 1.0),
}

TUNED_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "best_params_v1.json")


def load_tuned():
    if os.path.exists(TUNED_PATH):
        with open(TUNED_PATH) as f:
            return json.load(f)
    return None


class MyBot:
    def __init__(self, params=None, seed=None):
        self.p = dict(DEFAULT_PARAMS)
        if params:
            self.p.update(params)
        self.rng = random.Random(seed)
        self.stats = {}  # seat -> [hands seen, preflop shoves]

    # ---------- engine hooks ----------
    def get_action(self, s):
        try:
            return self.preflop(s) if s["street"] == 0 else self.postflop(s)
        except Exception:
            return self.passive(s)

    def on_hand_end(self, info):
        seen, shoved = set(), set()
        for street, seat, kind, _amt, allin in info["history"]:
            seen.add(seat)
            if street == 0 and kind == "raise" and allin:
                shoved.add(seat)
        for seat in seen:
            st = self.stats.setdefault(seat, [0, 0])
            st[0] += 1
            st[1] += seat in shoved

    # ---------- helpers ----------
    @staticmethod
    def passive(s):
        return ("check",) if s["to_call"] == 0 else ("fold",)

    @staticmethod
    def raise_to(s, target):
        if not s["can_raise"]:
            return ("call",)
        target = int(max(s["min_raise_to"], min(target, s["max_raise_to"])))
        if target >= 0.7 * s["max_raise_to"]:  # don't leave a sliver behind
            target = s["max_raise_to"]
        return ("raise", target)

    def is_maniac(self, seat):
        st = self.stats.get(seat)
        return bool(st) and st[0] >= 12 and st[1] / st[0] > self.p["maniac_rate"]

    @staticmethod
    def last_raiser(s):
        for street, seat, kind, _a, _ai in reversed(s["history"]):
            if street == s["street"] and kind == "raise":
                return seat
        return None

    @staticmethod
    def icm_pressure(s):
        return s["players_left"] <= 4 or s["hand_number"] >= 175

    # ---------- preflop ----------
    def preflop(self, s):
        p = self.p
        bb = s["big_blind"]
        pct = TABLE[hand_key(*s["hole"])]["pct"]
        me = s["seat"]
        mine = s["stack"] + s["bet"]
        biggest_other = max((v for t, v in s["stacks"].items() if t != me), default=mine)
        eff_bb = min(mine, biggest_other) / bb
        late = 1.0 - s["players_behind"] / max(1, s["players_left"] - 1)
        icm = p["bubble_tighten"] if self.icm_pressure(s) else 1.0
        to_call = s["to_call"]

        if s["current_bet"] <= bb:  # unopened (maybe limped)
            if eff_bb <= p["push_bb"]:
                rng = p["push_base"] * (p["push_bb"] / max(eff_bb, 1.0)) ** p["push_exp"]
                rng *= 1 + (p["push_late_mult"] - 1) * late
                return self.raise_to(s, s["max_raise_to"]) if pct <= rng else self.passive(s)
            if pct <= p["open_pct"] + p["open_late_bonus"] * late:
                limpers = sum(1 for st, _, k, _a, _ai in s["history"] if st == 0 and k == "call")
                return self.raise_to(s, bb * (p["open_size"] + limpers))
            return self.passive(s)

        widen = p["maniac_widen"] if self.is_maniac(self.last_raiser(s)) else 1.0
        if to_call >= 0.4 * s["stack"] or eff_bb <= p["push_bb"]:
            # effectively an all-in decision; cheaper prices justify wider calls
            odds = to_call / (s["pot"] + to_call)
            rng = p["call_allin_pct"] * icm * widen * max(0.5, 0.45 / max(odds, 0.05))
            return self.raise_to(s, s["max_raise_to"]) if pct <= min(rng, 1.0) else self.passive(s)
        if pct <= p["threebet_pct"] * widen:
            return self.raise_to(s, s["current_bet"] * 3)
        if pct <= p["call_raise_pct"] * icm * widen:
            return ("call",)
        return self.passive(s)

    # ---------- postflop ----------
    @staticmethod
    def made_strength(hole, board):
        v = evaluate(hole + board)
        cat = v >> 20
        bcat = evaluate(board) >> 20
        if cat <= bcat:
            return 0.12  # playing the board
        branks = sorted((c >> 2 for c in board), reverse=True)
        hranks = [c >> 2 for c in hole]
        if cat == PAIR:
            pr = ((v >> 16) & 15) - 1
            if hranks[0] == hranks[1] and pr > branks[0]:
                return 0.72  # overpair
            if pr == branks[0]:
                kicker = max((r for r in hranks if r != pr), default=12)
                return 0.6 if kicker >= 9 else 0.52  # top pair
            return 0.42 if pr >= branks[1] else 0.3
        if cat == TWO_PAIR:
            return 0.5 if bcat == PAIR else 0.78
        if cat == TRIPS:
            return 0.75 if bcat == PAIR else 0.86
        return {STRAIGHT: 0.87, FLUSH: 0.91, FULL_HOUSE: 0.96}.get(cat, 0.99)

    @staticmethod
    def draw_equity(hole, board, street):
        if street == 3:
            return 0.0
        cards = hole + board
        outs = 0.0
        for su in range(4):
            if sum(1 for c in cards if c & 3 == su) == 4 and any(c & 3 == su for c in hole):
                outs += 9
        mask = 0
        for c in cards:
            mask |= 1 << (c >> 2)
        if straight_high(mask) < 0:
            ranks = sum(1 for r in range(13) if not mask >> r & 1 and straight_high(mask | 1 << r) >= 0)
            outs += min(8, 4 * ranks) * (0.7 if outs else 1.0)
        return min(0.6, outs * (0.04 if street == 1 else 0.02))

    def postflop(self, s):
        p = self.p
        hole, board = list(s["hole"]), s["board"]
        n_opp = max(1, s["active_in_hand"] - 1)
        made = self.made_strength(hole, board) ** (1 + 0.6 * (n_opp - 1))
        e = max(made, self.draw_equity(hole, board, s["street"]))
        pot, to_call = s["pot"], s["to_call"]

        if to_call == 0:
            if e >= p["bet_eq"]:
                return self.raise_to(s, s["bet"] + p["value_frac"] * pot)
            raised_pre = any(st == 0 and seat == s["seat"] and k == "raise"
                             for st, seat, k, _a, _ai in s["history"])
            if raised_pre and n_opp == 1 and s["street"] == 1 and self.rng.random() < p["cbet"]:
                return self.raise_to(s, s["bet"] + 0.5 * pot)
            return ("check",)

        odds = to_call / (pot + to_call)
        if e >= p["raise_eq"]:
            return self.raise_to(s, s["current_bet"] + max(s["big_blind"], p["value_frac"] * (pot + to_call)))
        need = odds + p["call_margin"] + (p["icm_margin"] if self.icm_pressure(s) else 0.0)
        return ("call",) if e >= need else ("fold",)

bots.py:
"""Opponent pool approximating what a field of 60-minute bots looks like."""
import importlib.util
import os
import random

from cards import evaluate, category, PAIR
from preflop import TABLE, hand_key


def passive(s):
    return ("check",) if s["to_call"] == 0 else ("fold",)


def pct(s):
    return TABLE[hand_key(*s["hole"])]["pct"]


class RandomBot:
    def __init__(self, seed=None):
        self.rng = random.Random(seed)

    def get_action(self, s):
        r = self.rng.random()
        if s["to_call"] > 0 and r < 0.3:
            return ("fold",)
        if s["can_raise"] and r > 0.85:
            return ("raise", self.rng.randint(s["min_raise_to"], s["max_raise_to"]))
        return ("call",)


class ManiacBot:
    """Shoves wide preflop, fires pot-sized bets postflop."""

    def __init__(self, seed=None):
        self.rng = random.Random(seed)

    def get_action(self, s):
        if s["street"] == 0:
            if pct(s) <= 0.40 or self.rng.random() < 0.08:
                return ("raise", s["max_raise_to"])
            return passive(s)
        if self.rng.random() < 0.6 and s["can_raise"]:
            return ("raise", s["current_bet"] + s["pot"])
        return ("call",)


class StationBot:
    """Calls everything, never raises."""

    def get_action(self, s):
        return ("call",)


class RockBot:
    """Top ~6% only; continues postflop with a pair or better."""

    def get_action(self, s):
        if s["street"] == 0:
            if pct(s) <= 0.06:
                return ("raise", s["current_bet"] * 3 if s["stack"] > 15 * s["big_blind"] else s["max_raise_to"])
            return passive(s)
        if category(evaluate(list(s["hole"]) + s["board"])) >= PAIR:
            return ("raise", s["bet"] + s["pot"] // 2) if s["to_call"] == 0 else ("call",)
        return passive(s)


# ---------- Exact copies of Deep-ML's house bots (pokerbot_sdk/house_bots.py) ----------
def chen_strength(hole):
    """pokerbot_sdk.preflop_strength: Chen formula / 20, clipped to 0..1."""
    a, b = sorted(hole, key=lambda c: c >> 2, reverse=True)
    ra, rb = a >> 2, b >> 2
    score = {12: 10, 11: 8, 10: 7, 9: 6}.get(ra, (ra + 2) / 2)
    if ra == rb:
        score = max(score * 2, 5)
    if (a & 3) == (b & 3):
        score += 2
    gap = ra - rb - 1
    if ra != rb:
        score -= {0: 0, 1: 1, 2: 2, 3: 4}.get(gap, 5)
        if gap <= 1 and ra < 10:
            score += 1
    return max(0.0, min(1.0, score / 20))


def mc_equity(hole, board, opponents, samples, rng):
    """pokerbot_sdk.equity: Monte Carlo pot share vs `opponents` random hands."""
    known = set(hole) | set(board)
    rest = [c for c in range(52) if c not in known]
    need = 5 - len(board)
    draw = need + 2 * opponents
    total = 0.0
    for _ in range(samples):
        cards = rng.sample(rest, draw)
        full = list(board) + cards[:need]
        mine = evaluate(list(hole) + full)
        best, ties = 0, 0
        for k in range(opponents):
            v = evaluate(cards[need + 2 * k: need + 2 * k + 2] + full)
            if v > best:
                best, ties = v, 0
            if v == mine:
                ties += 1
        if mine > best:
            total += 1.0
        elif mine == best:
            total += 1.0 / (ties + 1)
    return total / samples


class HouseFold:
    def get_action(self, s):
        return passive(s)


class HouseCall:
    def get_action(self, s):
        return ("call",)


class HouseRaise:
    """Maniac: pot-sized raise whenever it can."""
    def get_action(self, s):
        if s["can_raise"]:
            return ("raise", s["current_bet"] + s["pot"])
        return ("call",)


class HouseRandom:
    def __init__(self, seed=None):
        self.rng = random.Random(seed)

    def get_action(self, s):
        roll = self.rng.random()
        if roll < 0.15 and s["to_call"]:
            return ("fold",)
        if roll < 0.75 or not s["can_raise"]:
            return ("call",)
        lo, hi = s["min_raise_to"], s["max_raise_to"]
        return ("raise", self.rng.randint(lo, max(lo, min(hi, lo + s["pot"]))))


class HouseTight:
    """Tight-aggressive baseline: Chen preflop chart, then 120-sample equity vs pot odds."""
    def __init__(self, seed=None, samples=120):
        self.rng = random.Random(seed)
        self.samples = samples

    def get_action(self, s):
        bb = s["big_blind"]
        if s["street"] == 0:
            st = chen_strength(s["hole"])
            if st >= 0.55 and s["can_raise"]:
                return ("raise", max(s["min_raise_to"], 3 * s["current_bet"]))
            if st >= 0.4 or s["to_call"] == 0:
                return ("call",) if (s["to_call"] <= 4 * bb or st >= 0.55) else ("fold",)
            return ("fold",)
        opp = max(1, s["active_in_hand"] - 1)
        eq = mc_equity(list(s["hole"]), s["board"], opp, self.samples, self.rng)
        if eq > 0.7 and s["can_raise"]:
            return ("raise", s["current_bet"] + (2 * s["pot"]) // 3)
        if s["to_call"] == 0:
            return ("check",)
        odds = s["to_call"] / (s["pot"] + s["to_call"])
        return ("call",) if eq > odds + 0.05 else ("fold",)


class CrashBot:
    """Simulates a broken or too-slow entry (engine auto check/folds it)."""

    def get_action(self, s):
        raise RuntimeError("bug")


FIELD = os.path.join(os.path.dirname(os.path.abspath(__file__)), "field")
_field_classes = {}


def field_bot(name):
    """Bots written independently by AI agents under the contest rules (field/<name>.py)."""
    if name not in _field_classes:
        spec = importlib.util.spec_from_file_location("field_" + name, os.path.join(FIELD, name + ".py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        _field_classes[name] = mod.Bot
    return _field_classes[name]()


AI_BOTS = ["specialist", "equity", "aggro", "learned"]


def make_bot(kind, seed=None):
    if kind in AI_BOTS:
        return field_bot(kind)
    from mybot_v1 import MyBot
    if kind == "random":
        return RandomBot(seed)
    if kind == "maniac":
        return ManiacBot(seed)
    if kind == "station":
        return StationBot()
    if kind == "rock":
        return RockBot()
    if kind == "h_tight":
        return HouseTight(seed)
    if kind == "h_call":
        return HouseCall()
    if kind == "h_random":
        return HouseRandom(seed)
    if kind == "h_raise":
        return HouseRaise()
    if kind == "h_fold":
        return HouseFold()
    if kind == "crash":
        return CrashBot()
    if kind == "tag":
        return MyBot(seed=seed)  # default-parameter copy of the v1 bot = a competent opponent
    if kind == "nit":
        return MyBot({"open_pct": 0.06, "open_late_bonus": 0.08, "push_base": 0.06,
                      "call_allin_pct": 0.04, "cbet": 0.3}, seed=seed)
    if kind == "lag":
        return MyBot({"open_pct": 0.3, "open_late_bonus": 0.3, "push_base": 0.25,
                      "call_allin_pct": 0.15, "cbet": 0.9, "call_margin": -0.05}, seed=seed)
    raise ValueError(kind)


# Sampled with replacement to fill the 7 opponent seats. Weight them toward what you expect.
POOLS = {
    "default": ["tag", "tag", "tag", "maniac", "station", "rock", "random", "crash"],
    "tight": ["tag", "tag", "nit", "nit", "rock", "rock", "tag", "lag"],
    "loose": ["lag", "lag", "maniac", "station", "station", "random", "tag", "crash"],
    "strong": ["tag", "tag", "tag", "nit", "lag", "lag", "tag", "rock"],
    # Deep-ML house bots (from play_local's seat list): tight, call, random, raise, tight, fold, random
    # exact house bots in pokerbot_sdk's DEFAULT_OPPONENTS order
    "house": ["h_tight", "h_call", "h_random", "h_raise", "h_tight", "h_fold", "h_random"],
    # AI-written contest bots: the closest stand-in for the real field
    "ai": ["specialist", "equity", "aggro", "learned"],
    "contest": ["specialist", "equity", "aggro", "learned", "specialist", "equity", "aggro", "learned",
                "tag", "lag", "nit", "station", "crash"],
}
POOL = POOLS["default"]

